import Foundation

/// Shared native locale selection and formatting policy. Catalog accessors are generated by XCStrings Tool.
public enum L10n {
    /// Follows the localization selected by Foundation from the module's native resources.
    public static var locale: Locale {
        guard let language = resourceBundle.preferredLocalizations.first else {
            preconditionFailure("Localization bundle must declare a development language")
        }
        return Locale(identifier: language)
    }

    static var resourceBundle: Bundle { .module }
}
